import json
import os
import requests
import time
from datetime import datetime

def main():
    input_data = json.load(input())
    client_id = input_data['client_id']
    client_secret = input_data['client_secret']
    auth_url = input_data['auth_url']
    api_base = input_data['api_base']
    report_ids = input_data['report_ids']

    # Load or fetch access token
    token_file = './token.json'
    if os.path.exists(token_file):
        with open(token_file, 'r') as f:
            saved_token = json.load(f)
            if saved_token['client_id'] == client_id and (time.time() - saved_token['expires_at']) > 60:
                access_token = saved_token['access_token']
            else:
                access_token = None
    else:
        access_token = None

    if access_token is None:
        response = requests.post(auth_url, data={
            'grant_type': 'client_credentials',
            'client_id': client_id,
            'client_secret': client_secret
        })
        if response.status_code == 200:
            token_data = response.json()
            expires_at = time.time() + token_data['expires_in']
            with open(token_file, 'w') as f:
                json.dump({
                    'access_token': token_data['access_token'],
                    'expires_at': expires_at,
                    'client_id': client_id
                }, f)
            access_token = token_data['access_token']
        else:
            print("failed")
            exit(1)

    # Fetch reports
    os.makedirs('./out', exist_ok=True)
    success = True
    for report_id in report_ids:
        url = f"{api_base}/reports/{report_id}"
        headers = {'Authorization': f'Bearer {access_token}'}

        try:
            response = requests.get(url, headers=headers)
            if response.status_code == 200:
                with open(f'./out/{report_id}.json', 'wb') as f:
                    f.write(response.content)
                print(f"{report_id} {response.status_code}")
            else:
                print(f"{report_id} failed")
                success = False
        except Exception:
            print(f"{report_id} failed")
            success = False

    exit(0 if success else 1)

if __name__ == "__main__":
    main()
